// Package brand embeds the sleeping sloth (variant c2) so the app can show it in its resting
// states. The files are generated by generate.py in this folder.
package brand

import _ "embed"

// SleepingPNG is the 128 px export, used with the Kitty graphics protocol.
//
//go:embed reposo/lazymark-128.png
var SleepingPNG []byte

// SleepingSVG is the 32x32 pixel grid, used for the half-block fallback.
//
//go:embed reposo/lazymark.svg
var SleepingSVG string
